const file = 'data/pilot-places.json'
const places = JSON.parse(await readFile(file, 'utf8'))
const byKey = new Map(places.map((place) => [place.sourceKey, place]))
const checkedAt = '2026-10-27'

function addSource(place, fieldKey, sourceName, sourceUrl, sourceType = 'official') {
  const exists = place.sources.some((s) => s.fieldKey === fieldKey && s.sourceName === sourceName && s.sourceUrl === sourceUrl && s.sourceType === sourceType)
  if (!exists) place.sources.push({ fieldKey, sourceName, sourceUrl, sourceType, checkedAt })
}

function setSourced(place, fieldKey, value, sourceName, sourceUrl, sourceType = 'official') {
  place[fieldKey] = value
  if (value !== null && value !== '' && !(Array.isArray(value) && value.length === 0)) addSource(place, fieldKey, sourceName, sourceUrl, sourceType)
}

function setLocation(key, lat, lng, objectType, objectId, name) {
  const place = byKey.get(key)
  if (!place) throw new Error(`Missing place ${key}`)
  place.location = { lat, lng }
  addSource(place, 'location', `OpenStreetMap ${objectType} ${objectId} - ${name}`, `https://www.openstreetmap.org/${objectType}/${objectId}`, 'openstreetmap')
}

