function makePlace({ sourceKey, name, category, barangay, address = null, location = null, description, services = [], publicPhone = null, publicEmail = null }) {
  const record = {
    sourceKey, name, category, barangay, address, location, description, services, publicPhone, publicEmail,
    access: { entranceNotes: '', wheelchairAccess: 'unknown', parkingNotes: null, hoursNote: null, additionalNotes: null },
    sources: [],
  }
  places.push(record)
  byKey.set(sourceKey, record)
  return record
}

function officialFields(record, fieldKeys, sourceName, sourceUrl) {
  for (const fieldKey of fieldKeys) addSource(record, fieldKey, sourceName, sourceUrl)
}

